  function loadUserData() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY) || localStorage.getItem(LEGACY_STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        userData = { ...userData, ...parsed };
        if (!parsed.uiRedesignV18Applied) {
          userData.theme = 'light';
          userData.layoutMode = 'paragraph';
          userData.fontFamily = 'merriweather';
          userData.uiRedesignV18Applied = true;
          localStorage.setItem(STORAGE_KEY, JSON.stringify(userData));
        }
        // Migrate legacy fontScale -> fontSize (px)
        if (typeof parsed.fontSize !== 'number') {
          const scale = typeof parsed.fontScale === 'number' ? parsed.fontScale : 1;
          userData.fontSize = Math.max(14, Math.min(32, Math.round(19 * scale)));
        }
        // Migrate legacy lineHeight string -> numeric
        if (typeof userData.lineHeight === 'string') {
          const legacyLeading = { compact: 1.4, normal: 1.7, relaxed: 2.1 };
          userData.lineHeight = legacyLeading[userData.lineHeight] || 1.7;
        }
      }
    } catch (e) {
      console.warn('No se pudo leer localStorage:', e);
    }
  }

  function saveUserData() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(userData));
      updateSavedBadge();
      updateReadingProgressUI();
    } catch (e) {
      console.warn('No se pudo guardar en localStorage:', e);
    }
  }

  function showToast(msg) {
    const toast = document.getElementById('toast');
    if (!toast) return;
    toast.textContent = msg;
    toast.classList.remove('hidden');
    clearTimeout(showToast._timer);
    showToast._timer = setTimeout(() => {
      toast.classList.add('hidden');
    }, 2600);
  }

  function populateFontSelect() {
    const sel = document.getElementById('fontFamilySelect');
    if (!sel || sel.options.length > 0) return;
    FONT_CATALOG.forEach((f) => {
      const opt = document.createElement('option');
      opt.value = f.id;
      opt.textContent = f.label;
      sel.appendChild(opt);
    });
  }

  function updateRangeFill(inputEl) {
    if (!inputEl) return;
    const min = parseFloat(inputEl.min) || 0;
    const max = parseFloat(inputEl.max) || 100;
    const val = parseFloat(inputEl.value) || min;
    const pct = Math.max(0, Math.min(100, ((val - min) / (max - min)) * 100));
    inputEl.style.setProperty('--range-pct', `${pct}%`);
  }

  // Apply visual settings (10 themes, 50 fonts, font style, px size, line-height, layout & options)
  function applyAppearance() {
    populateFontSelect();

    const activeThemeKey = THEMES_CATALOG[userData.theme] ? userData.theme : 'light';
    document.documentElement.setAttribute('data-theme', activeThemeKey);

    const themeInfo = THEMES_CATALOG[activeThemeKey];
    const currentThemeName = document.getElementById('currentThemeName');
    const currentThemeDot = document.getElementById('currentThemeDot');
    if (currentThemeName) currentThemeName.textContent = themeInfo.label;
    if (currentThemeDot) currentThemeDot.style.backgroundColor = themeInfo.dot;

    // 50 Fonts
    const fontObj = FONT_CATALOG.find((f) => f.id === userData.fontFamily) || FONT_CATALOG[0];
    ensureGoogleFontLoaded(fontObj);
    document.documentElement.style.setProperty('--reader-font', fontObj.family);
    const fontSelect = document.getElementById('fontFamilySelect');
    if (fontSelect) fontSelect.value = fontObj.id;
    const fontDesc = document.getElementById('fontFamilyDesc');
    if (fontDesc) fontDesc.textContent = fontObj.desc;

    // Font Style (weight / italic)
    const styleKey = FONT_STYLES[userData.fontStyle] ? userData.fontStyle : 'normal';
    const styleObj = FONT_STYLES[styleKey];
    document.documentElement.style.setProperty('--reader-font-weight', styleObj.weight);
    document.documentElement.style.setProperty('--reader-font-style', styleObj.style);
    const currentFontStyleName = document.getElementById('currentFontStyleName');
    if (currentFontStyleName) currentFontStyleName.textContent = styleObj.label;
    document.querySelectorAll('[data-set-fontstyle]').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.setFontstyle === styleKey);
    });

    // Font Size (px)
    const fontSize = Math.max(14, Math.min(32, Math.round(Number(userData.fontSize) || 19)));
    document.documentElement.style.setProperty('--reader-font-size', `${fontSize}px`);
    const fontSizeLabel = document.getElementById('fontSizeLabel');
    if (fontSizeLabel) fontSizeLabel.textContent = `${fontSize} px`;
    const fontSizeRange = document.getElementById('fontSizeRange');
    if (fontSizeRange) {
      fontSizeRange.value = String(fontSize);
      updateRangeFill(fontSizeRange);
    }

    // Line Height (1.2 - 2.4)
    const rawLeading = typeof userData.lineHeight === 'number'
      ? userData.lineHeight
      : parseFloat(userData.lineHeight) || 1.7;
    const leadingVal = Math.max(1.2, Math.min(2.4, Math.round(rawLeading * 10) / 10));
    document.documentElement.style.setProperty('--reader-leading', String(leadingVal));
    const lineHeightLabel = document.getElementById('lineHeightLabel');
    if (lineHeightLabel) lineHeightLabel.textContent = leadingVal.toFixed(1);
    const lineHeightRange = document.getElementById('lineHeightRange');
    if (lineHeightRange) {
      lineHeightRange.value = leadingVal.toFixed(1);
      updateRangeFill(lineHeightRange);
    }
    document.querySelectorAll('[data-set-leading]').forEach((btn) => {
      btn.classList.toggle('active', Math.abs(parseFloat(btn.dataset.setLeading) - leadingVal) < 0.05);
    });

    // Text Alignment
    const alignVal = userData.textAlign === 'justify' ? 'justify' : 'left';
    document.documentElement.style.setProperty('--reader-align', alignVal);
    document.querySelectorAll('[data-set-align]').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.setAlign === alignVal);
    });

    // Theme & Layout active states
    document.querySelectorAll('[data-set-theme]').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.setTheme === activeThemeKey);
    });
    document.querySelectorAll('[data-set-layout]').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.setLayout === userData.layoutMode);
    });

    // Checkboxes
    const showNums = userData.showVerseNumbers !== false;
    const chkNums = document.getElementById('chkVerseNumbers');
    if (chkNums) chkNums.checked = showNums;

    const showHeadings = userData.showHeadings !== false;
    const chkHeadings = document.getElementById('chkBiblicalHeadings');
    if (chkHeadings) chkHeadings.checked = showHeadings;

    const highlightOT = !!userData.highlightOTQuotes;
    const chkOT = document.getElementById('chkHighlightOT');
    if (chkOT) chkOT.checked = highlightOT;

    const isRedOn = userData.redLetters !== false;
    const chkRed = document.getElementById('chkRedLetters');
    if (chkRed) chkRed.checked = isRedOn;

    // Update Modo RAE states
    const isRaeOn = !!userData.raeMode;
    document.body.classList.toggle('rae-mode', isRaeOn);
    const chkRae = document.getElementById('chkRaeMode');
    if (chkRae) chkRae.checked = isRaeOn;

    const btnRaeQuick = document.getElementById('btnToggleRaeQuick');
    if (btnRaeQuick) {
      btnRaeQuick.classList.toggle('active', isRaeOn);
      btnRaeQuick.title = isRaeOn
        ? 'Modo RAE Activado: Toca cualquier palabra para buscarla en la RAE (clic para desactivar)'
        : 'Activar Modo Diccionario RAE (busca cualquier palabra al hacer clic)';
    }

    const chapterHint = document.getElementById('chapterHint');
    const chapterRaeHint = document.getElementById('chapterRaeHint');
    if (chapterHint && chapterRaeHint) {
      chapterHint.classList.toggle('hidden', isRaeOn);
      chapterRaeHint.classList.toggle('hidden', !isRaeOn);
    }

    const raeSubOptions = document.getElementById('raeSubOptions');
    if (raeSubOptions) {
      raeSubOptions.classList.toggle('hidden', !isRaeOn);
    }

    const currentDisambig = userData.raeDisambig || 'smart';
    document.querySelectorAll('[data-set-raedisambig]').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.setRaedisambig === currentDisambig);
    });

    const versesList = document.getElementById('versesList');
    if (versesList) {
      versesList.classList.toggle('paragraph-mode', userData.layoutMode === 'paragraph');
      versesList.classList.toggle('hide-verse-nums', !showNums);
      versesList.classList.toggle('hide-headings', !showHeadings);
    }

    // Sincronizar vista previa en vivo dentro del panel de Ajustes
    const previewText = document.getElementById('settingsPreviewText');
    if (previewText) {
      previewText.classList.toggle('paragraph-mode', userData.layoutMode === 'paragraph');
      previewText.classList.toggle('hide-verse-nums', !showNums);
      previewText.classList.toggle('hide-headings', !showHeadings);
    }
    const previewJesusText = document.getElementById('previewJesusText');
    if (previewJesusText) {
      previewJesusText.classList.toggle('words-of-jesus', isRedOn);
    }
    const previewOtQuote = document.getElementById('previewOtQuote');
    if (previewOtQuote) {
      previewOtQuote.classList.toggle('ot-quote', highlightOT);
    }

    const chapterHeader = document.querySelector('.chapter-header');
    if (chapterHeader) {
      chapterHeader.classList.toggle('hide-headings', !showHeadings);
    }
  }

  // Ensure every book has canonical Spanish accented name, abbrev, category, and testament
  function applyCanonicalMetadata(rawBooks) {
    if (!Array.isArray(rawBooks)) return [];
    return rawBooks.map((book, idx) => {
      const canonical = CANONICAL_BOOKS[idx];
      if (!canonical) return book;
      return {
        ...book,
        name: canonical.name,
        abbrev: canonical.abbrev,
        category: canonical.category,
        testament: canonical.testament
      };
    });
  }

  // Render Sidebar Books List
  function renderBookList() {
    const container = document.getElementById('bookListContainer');
    const filterInput = document.getElementById('bookFilterInput');
    if (!container || !filterInput) return;
    const filterVal = normalizeStr(filterInput.value.trim());
    container.innerHTML = '';

    let lastCat = '';
    bibleData.forEach((book, idx) => {
      if (activeTestamentFilter !== 'ALL' && book.testament !== activeTestamentFilter) return;
      if (filterVal) {
        const matchName = normalizeStr(book.name).includes(filterVal);
        const matchAbbrev = normalizeStr(book.abbrev).includes(filterVal);
        if (!matchName && !matchAbbrev) return;
      }

      if (book.category !== lastCat && !filterVal) {
        lastCat = book.category;
        const catEl = document.createElement('div');
        catEl.className = 'book-category-header';
        catEl.textContent = book.category;
        container.appendChild(catEl);
      }

      let readCount = 0;
      const totalCh = book.chapters.length;
      for (let c = 0; c < totalCh; c++) {
        if (userData.readChapters[`${idx}-${c}`]) readCount++;
      }

      const btn = document.createElement('button');
      btn.className = 'book-item' + (idx === currentBookIdx ? ' active' : '');
      btn.innerHTML = `
        <span class="book-item-left">
          <span class="book-abbrev">${escapeHtml(book.abbrev)}</span>
          <span>${escapeHtml(book.name)}</span>
        </span>
        <span class="book-chapters-count ${readCount === totalCh ? 'book-item-read-done' : ''}">
          ${readCount > 0 ? `${readCount}/${totalCh}` : totalCh}
        </span>
      `;
      btn.addEventListener('click', () => {
        navigateTo(idx, 0);
        if (window.innerWidth <= 860) {
          toggleSidebar(false);
        }
      });
      container.appendChild(btn);
    });
  }

  // Navigate to Book, Chapter, and optional Verse
  function navigateTo(bookIdx, chapterIdx, targetVerseIdx = null, pushHist = true) {
    if (!bibleData.length) return;

    bookIdx = Math.max(0, Math.min(bibleData.length - 1, bookIdx));
    const book = bibleData[bookIdx];
    chapterIdx = Math.max(0, Math.min(book.chapters.length - 1, chapterIdx));

    currentBookIdx = bookIdx;
    currentChapterIdx = chapterIdx;
    selectedVerses.clear();
    updateSelectionToolbar();

    userData.lastLocation = { b: bookIdx, c: chapterIdx };
    if (pushHist) {
      userData.history = [
        { b: bookIdx, c: chapterIdx, ts: Date.now() },
        ...userData.history.filter((h) => !(h.b === bookIdx && h.c === chapterIdx))
      ].slice(0, 40);
    }
    saveUserData();

    const hashRef = `#${encodeURIComponent(book.abbrev)}-${chapterIdx + 1}${targetVerseIdx !== null ? `-${targetVerseIdx + 1}` : ''}`;
    history.replaceState(null, '', hashRef);

    renderChapter();
    renderBookList();

    const mainScroll = document.getElementById('mainScroll');
    if (targetVerseIdx !== null) {
      setTimeout(() => {
        const vEl = document.getElementById(`verse-${targetVerseIdx}`);
        if (vEl) {
          vEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
          vEl.classList.add('flash-target');
          setTimeout(() => vEl.classList.remove('flash-target'), 2400);
        }
      }, 60);
    } else if (mainScroll) {
      mainScroll.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  // Render Current Chapter
  function renderChapter() {
    const book = bibleData[currentBookIdx];
    const verses = book.chapters[currentChapterIdx];
    const testamentFull = book.testament === 'AT' ? 'Antiguo Testamento' : 'Nuevo Testamento';

    document.getElementById('currentCategoryBadge').textContent = `${book.category} · ${testamentFull}`;
    document.getElementById('currentChapterTitle').textContent = `${book.name} ${currentChapterIdx + 1}`;
    const topbarLabel = document.getElementById('topbarChapterLabel');
    if (topbarLabel) topbarLabel.textContent = `${book.name} ${currentChapterIdx + 1}`;
    document.getElementById('gridBookName').textContent = book.name;
    document.getElementById('chapterVerseCount').textContent = `${verses.length} versículos`;
    const scopeBookBtn = document.getElementById('scopeCurrentBookBtn');
    if (scopeBookBtn) scopeBookBtn.innerHTML = `Solo<br />${escapeHtml(book.name)}`;

    const btnPrevTop = document.getElementById('btnPrevChapterTop');
    const btnNextTop = document.getElementById('btnNextChapterTop');
    if (btnPrevTop) btnPrevTop.classList.toggle('is-edge', currentBookIdx === 0 && currentChapterIdx === 0);
    if (btnNextTop) {
      const isLast =
        currentBookIdx === bibleData.length - 1 &&
        currentChapterIdx === book.chapters.length - 1;
      btnNextTop.classList.toggle('is-edge', isLast);
    }

    const verseSelect = document.getElementById('verseJumpSelect');
    verseSelect.innerHTML = '';
    for (let i = 0; i < verses.length; i++) {
      const opt = document.createElement('option');
      opt.value = i;
      opt.textContent = i + 1;
      verseSelect.appendChild(opt);
    }

    const gridContainer = document.getElementById('chapterNumbersGrid');
    gridContainer.innerHTML = '';
    for (let c = 0; c < book.chapters.length; c++) {
      const chBtn = document.createElement('button');
      const isRead = !!userData.readChapters[`${currentBookIdx}-${c}`];
      chBtn.className =
        'ch-num-btn' +
        (c === currentChapterIdx ? ' active' : '') +
        (isRead ? ' read-done' : '');
      chBtn.textContent = c + 1;
      chBtn.addEventListener('click', () => {
        document.getElementById('chapterGridPanel').classList.add('hidden');
        navigateTo(currentBookIdx, c);
      });
      gridContainer.appendChild(chBtn);
    }

    updateReadButtonUI();

    const prevInfo = getAdjacentChapter(-1);
    const nextInfo = getAdjacentChapter(1);
    document.getElementById('prevChapterName').textContent = `${bibleData[prevInfo.b].name} ${prevInfo.c + 1}`;
    document.getElementById('nextChapterName').textContent = `${bibleData[nextInfo.b].name} ${nextInfo.c + 1}`;

    const versesList = document.getElementById('versesList');
    versesList.classList.toggle('paragraph-mode', userData.layoutMode === 'paragraph');
    versesList.classList.toggle('hide-verse-nums', userData.showVerseNumbers === false);
    versesList.classList.toggle('hide-headings', userData.showHeadings === false);
    versesList.innerHTML = '';

    verses.forEach((vText, vIdx) => {
      const key = makeKey(currentBookIdx, currentChapterIdx, vIdx);
      const headingText = PASSAGE_HEADINGS[key];
      if (headingText) {
        const hEl = document.createElement('div');
        hEl.className = 'passage-heading';
        hEl.textContent = headingText;
        versesList.appendChild(hEl);
      }

      const hlColor = userData.highlights[key];
      const isFav = !!userData.favorites[key];
      const noteObj = userData.notes[key];

      const vEl = document.createElement('div');
      const isOtQuote =
        userData.highlightOTQuotes &&
        currentBookIdx >= 39 &&
        /(escrito está|como está escrito|dicho por el profeta|dice el señor|por boca de|la escritura dice)/i.test(vText);
      vEl.className =
        'verse-item' +
        (selectedVerses.has(vIdx) ? ' selected' : '') +
        (isOtQuote ? ' ot-quote' : '');
      vEl.id = `verse-${vIdx}`;
      if (hlColor) vEl.setAttribute('data-hl', hlColor);

      let badgesHtml = '';
      if (isFav || noteObj) {
        badgesHtml = `<span class="verse-badges">
          ${isFav ? '<span class="v-badge" title="Favorito">★</span>' : ''}
          ${noteObj ? '<span class="v-badge" title="Tiene nota">✎ Nota</span>' : ''}
        </span>`;
      }

      let noteBoxHtml = '';
      if (noteObj && noteObj.text) {
        noteBoxHtml = `<span class="verse-note-box"><strong>Nota:</strong> ${escapeHtml(noteObj.text)}</span>`;
      }

      vEl.innerHTML = `<sup class="verse-num">${vIdx + 1}</sup><span class="verse-text">${formatVerseHtml(vText, currentBookIdx, currentChapterIdx, vIdx)}</span>${badgesHtml}${noteBoxHtml} `;

      vEl.addEventListener('click', (e) => {
        // If Modo RAE is enabled and user clicked on a word, process RAE lookup
        const raeToken = e.target.closest('.rae-token');
        if (userData.raeMode && raeToken) {
          e.preventDefault();
          e.stopPropagation();
          handleRaeWordClick(raeToken, vIdx);
          return;
        }

        // Allow native long-press text selection on mobile without accidentally toggling the verse
        const nativeSelection = window.getSelection ? window.getSelection().toString().trim() : '';
        if (nativeSelection.length > 0) return;

        if (selectedVerses.has(vIdx)) {
          selectedVerses.delete(vIdx);
          vEl.classList.remove('selected');
        } else {
          selectedVerses.add(vIdx);
          vEl.classList.add('selected');
        }
        updateSelectionToolbar();
      });

      versesList.appendChild(vEl);
    });
  }

  function escapeHtml(str) {
    return String(str)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function getRedLetterSpans(bIdx, cIdx, vIdx, textLen) {
    if (userData.redLetters === false) return null;
    const entry = RED_LETTERS_MAP[`${bIdx}-${cIdx}-${vIdx}`];
    if (entry === undefined) return null;
    if (typeof entry === 'number') {
      return [[entry, textLen]];
    }
    const spans = [];
    for (let i = 0; i < entry.length; i += 2) {
      spans.push([entry[i], entry[i + 1]]);
    }
    return spans;
  }

  function wrapTokensHtml(segmentText, vIdx, offsetRef) {
    if (!segmentText) return '';
    return segmentText.replace(/([a-zA-ZáéíóúüñÁÉÍÓÚÜÑ]+)/gu, (match) => {
      const idx = offsetRef ? offsetRef.offset++ : 0;
      const escaped = escapeHtml(match);
      const idxAttr = (offsetRef && vIdx !== null && vIdx !== undefined) ? ` data-word-idx="${idx}" data-vidx="${vIdx}"` : '';
      return `<span class="rae-token" data-word="${escaped}"${idxAttr}>${escaped}</span>`;
    });
  }

  function formatSegmentHtml(segmentText, normTerms, vIdx = null, offsetRef = null) {
    if (normTerms && normTerms.length) {
      return highlightQueryTerms(segmentText, normTerms);
    }
    if (vIdx !== null && vIdx !== undefined && offsetRef) {
      return wrapTokensHtml(segmentText, vIdx, offsetRef);
    }
    return escapeHtml(segmentText);
  }

  function formatVerseHtml(vText, bIdx, cIdx, vIdx, normTerms = null) {
    const text = String(vText || '');
    const offsetRef = { offset: 0 };
    const spans = getRedLetterSpans(bIdx, cIdx, vIdx, text.length);
    if (!spans || !spans.length) {
      return formatSegmentHtml(text, normTerms, vIdx, offsetRef);
    }
    let html = '';
    let lastIdx = 0;
    for (let i = 0; i < spans.length; i++) {
      const [start, end] = spans[i];
      if (start > lastIdx) {
        html += formatSegmentHtml(text.slice(lastIdx, start), normTerms, vIdx, offsetRef);
      }
      if (end > start) {
        html += `<span class="words-of-jesus">${formatSegmentHtml(text.slice(start, end), normTerms, vIdx, offsetRef)}</span>`;
      }
      lastIdx = end;
    }
    if (lastIdx < text.length) {
      html += formatSegmentHtml(text.slice(lastIdx), normTerms, vIdx, offsetRef);
    }
    return html;
  }

  // Handle click on word in Modo RAE
  function handleRaeWordClick(raeToken, vIdx) {
    const rawWord = raeToken.dataset.word;
    const wordIdx = parseInt(raeToken.dataset.wordIdx, 10);
    const book = bibleData[currentBookIdx];
    const verseText = (book && book.chapters[currentChapterIdx]) ? book.chapters[currentChapterIdx][vIdx] : '';

    const analysis = SpanishGrammarEngine.analyzeWord(rawWord, wordIdx, verseText);
    activeRaeAnalysis = { ...analysis, verseText, vIdx };

    // If user prefers asking on ambiguous words (e.g. vino = verbo o sustantivo)
    if (userData.raeDisambig === 'confirm' && analysis.isAmbiguous) {
      openRaeDisambigModal(rawWord, analysis, verseText);
      return;
    }

    // Direct mode: navigate directly to the RAE page of the distinguished category
    openRaeDictionary(analysis.lemma);

    // Show feedback toast with category distinction
    showRaeFeedbackToast(rawWord, analysis);
  }

  function openRaeDictionary(lemma) {
    if (!lemma) return;
    const raeUrl = `https://dle.rae.es/${encodeURIComponent(lemma)}`;

    // Create an anchor with target="_blank" to ensure opening in a new external browser tab/window.
    // NEVER redirect window.location.href, as that unloads/closes the standalone Bible PWA!
    try {
      const link = document.createElement('a');
      link.href = raeUrl;
      link.target = '_blank';
      link.rel = 'noopener noreferrer';
      link.style.display = 'none';
      document.body.appendChild(link);
      link.click();
      setTimeout(() => {
        if (link.parentNode) link.parentNode.removeChild(link);
      }, 150);
    } catch (err) {
      window.open(raeUrl, '_blank', 'noopener,noreferrer');
    }
  }

  function showRaeFeedbackToast(rawWord, analysis) {
    const toast = document.getElementById('toast');
    if (!toast) return;

    const catBadge = analysis.category === 'VERBO' ? '⚡ Verbo' : '📘 Sustantivo';
    let html = `<span>📖 RAE: <strong>${catBadge}</strong> «<strong>${escapeHtml(analysis.lemma)}</strong>» <small>(${escapeHtml(analysis.rawWord)})</small></span>`;

    if (analysis.isAmbiguous && analysis.alternative) {
      const altCat = analysis.alternative.category === 'VERBO' ? 'verbo' : 'sustantivo';
      const altLemma = analysis.alternative.lemma;
      html += ` <button type="button" class="toast-switch-btn" id="btnToastRaeAlt" data-alt-lemma="${escapeHtml(altLemma)}">¿Abrir como ${altCat} («${escapeHtml(altLemma)}»)?</button>`;
      toast.classList.add('toast-has-action');
    } else {
      toast.classList.remove('toast-has-action');
    }

    toast.innerHTML = html;
    toast.classList.remove('hidden');

    const btnAlt = document.getElementById('btnToastRaeAlt');
    if (btnAlt) {
      btnAlt.onclick = (e) => {
        e.stopPropagation();
        openRaeDictionary(btnAlt.dataset.altLemma);
        toast.classList.add('hidden');
        toast.classList.remove('toast-has-action');
      };
    }

    clearTimeout(showToast._timer);
    showToast._timer = setTimeout(() => {
      toast.classList.add('hidden');
      toast.classList.remove('toast-has-action');
    }, 4500);
  }

  function openRaeDisambigModal(rawWord, analysis, verseText) {
    const modal = document.getElementById('raeDisambigModal');
    if (!modal) return;

    document.getElementById('raeModalWordTitle').textContent = `Palabra: «${analysis.rawWord}»`;
    document.getElementById('raeVerbLemmaText').textContent = analysis.verbLemma;
    document.getElementById('raeVerbDescText').textContent = analysis.verbDesc || `Forma del verbo ${analysis.verbLemma}`;
    document.getElementById('raeNounLemmaText').textContent = analysis.nounLemma;
    document.getElementById('raeNounDescText').textContent = analysis.nounDesc || `Sustantivo ${analysis.nounLemma}`;

    const snippetEl = document.getElementById('raeVerseContextSnippet');
    if (snippetEl) {
      snippetEl.textContent = `«...${verseText.slice(0, 140)}...»`;
    }

    modal.classList.remove('hidden');
  }

  function closeRaeDisambigModal() {
    const modal = document.getElementById('raeDisambigModal');
    if (modal) modal.classList.add('hidden');
  }

  function getAdjacentChapter(dir) {
    let b = currentBookIdx;
    let c = currentChapterIdx + dir;
    if (c < 0) {
      b = (b - 1 + bibleData.length) % bibleData.length;
      c = bibleData[b].chapters.length - 1;
    } else if (c >= bibleData[b].chapters.length) {
      b = (b + 1) % bibleData.length;
      c = 0;
    }
    return { b, c };
  }

  // Universal Copy to Clipboard (works on all mobile browsers, iOS Safari, Android WebView & PC)
  async function copyTextToClipboard(text, successMsg = '📋 Copiado al portapapeles') {
    if (!text) return false;
    try {
      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        await navigator.clipboard.writeText(text);
        showToast(successMsg);
        return true;
      }
    } catch (e) {
      // Fallback below for mobile contexts where navigator.clipboard is restricted
    }

    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.setAttribute('readonly', '');
      ta.style.position = 'fixed';
      ta.style.top = '-9999px';
      ta.style.left = '-9999px';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      ta.setSelectionRange(0, text.length);
      const ok = document.execCommand('copy');
      document.body.removeChild(ta);
      if (ok) {
        showToast(successMsg);
        return true;
      }
    } catch (err) {}

    showToast('No se pudo copiar automáticamente');
    return false;
  }

  // Share text directly via WhatsApp (Mobile App or WhatsApp Web)
  function shareViaWhatsApp(text) {
    if (!text) return;
    const waUrl = `https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`;
    window.open(waUrl, '_blank', 'noopener,noreferrer');
  }

  function formatSingleVerseForShare(bookName, chIdx, vIdx, verseText, forWhatsApp = false, noteText = '') {
    const ref = `${bookName} ${chIdx + 1}:${vIdx + 1}`;
    let msg = `${vIdx + 1} ${verseText}\n_(${ref})_`;
    if (noteText) {
      msg += forWhatsApp ? `\n\n📝 _Nota: ${noteText}_` : `\n\nNota: ${noteText}`;
    }
    return msg;
  }

