  function formatVerseRange(sortedIndices) {
    if (!sortedIndices.length) return '';
    const nums = sortedIndices.map((i) => i + 1);
    const ranges = [];
    let start = nums[0];
    let prev = nums[0];
    for (let i = 1; i < nums.length; i++) {
      if (nums[i] === prev + 1) {
        prev = nums[i];
      } else {
        ranges.push(start === prev ? `${start}` : `${start}-${prev}`);
        start = nums[i];
        prev = nums[i];
      }
    }
    ranges.push(start === prev ? `${start}` : `${start}-${prev}`);
    return ranges.join(', ');
  }

  function getSelectedFormattedText(forWhatsApp = false) {
    const sorted = Array.from(selectedVerses).sort((a, b) => a - b);
    if (!sorted.length) return '';
    const book = bibleData[currentBookIdx];
    const chVerses = book.chapters[currentChapterIdx];
    const body = sorted
      .map((vIdx) => `${vIdx + 1} ${chVerses[vIdx]}`)
      .join('\n');
    const ref = `${book.name} ${currentChapterIdx + 1}:${formatVerseRange(sorted)}`;
    return `${body}\n_(${ref})_`;
  }

  // Smart Reference Parser
  function parseBibleReference(input) {
    const clean = normalizeStr(input).trim();
    if (!clean) return null;

    const match = clean.match(/^([1-3]?\s*[a-z]+)\s*(\d+)?(?:[:.\s](\d+))?$/);
    if (!match) return null;

    let bookQuery = match[1].replace(/\s+/g, ' ').trim();
    if (bookQuery === 'salmo') bookQuery = 'salmos';
    if (bookQuery === 'cantar' || bookQuery === 'cantar de los cantares') bookQuery = 'cantares';
    if (bookQuery === 'apocalipsis' || bookQuery === 'revelacion') bookQuery = 'apocalipsis';

    const chNum = match[2] ? parseInt(match[2], 10) : 1;
    const vNum = match[3] ? parseInt(match[3], 10) : null;

    let foundBookIdx = bibleData.findIndex(
      (b) => normalizeStr(b.name) === bookQuery || normalizeStr(b.abbrev) === bookQuery
    );
    if (foundBookIdx === -1) {
      foundBookIdx = bibleData.findIndex((b) => normalizeStr(b.name).startsWith(bookQuery));
    }
    if (foundBookIdx === -1) return null;

    if (!match[2]) {
      const exactBook = bibleData.findIndex(
        (b) => normalizeStr(b.name) === bookQuery || normalizeStr(b.abbrev) === bookQuery
      );
      if (exactBook === -1) return null;
      foundBookIdx = exactBook;
    }

    const book = bibleData[foundBookIdx];
    const cIdx = Math.max(0, Math.min(book.chapters.length - 1, chNum - 1));
    const vIdx =
      vNum !== null
        ? Math.max(0, Math.min(book.chapters[cIdx].length - 1, vNum - 1))
        : null;

    return { b: foundBookIdx, c: cIdx, v: vIdx };
  }

  function createCardActionsHtml() {
    return `
      <div class="card-quick-actions">
        <button type="button" class="card-action-btn act-copy" title="Copiar versículo">📋 Copiar</button>
        <button type="button" class="card-action-btn act-wa" title="Enviar por WhatsApp">💬 WhatsApp</button>
        <span class="card-open-link">Ir al pasaje →</span>
      </div>
    `;
  }

  function bindCardQuickActions(card, bookName, cIdx, vIdx, verseText, onNavigate, noteText = '') {
    const btnCopy = card.querySelector('.act-copy');
    const btnWa = card.querySelector('.act-wa');
    if (btnCopy) {
      btnCopy.addEventListener('click', (e) => {
        e.stopPropagation();
        copyTextToClipboard(formatSingleVerseForShare(bookName, cIdx, vIdx, verseText, false, noteText));
      });
    }
    if (btnWa) {
      btnWa.addEventListener('click', (e) => {
        e.stopPropagation();
        shareViaWhatsApp(formatSingleVerseForShare(bookName, cIdx, vIdx, verseText, true, noteText));
      });
    }
    card.addEventListener('click', () => {
      const nativeSelection = window.getSelection ? window.getSelection().toString().trim() : '';
      if (nativeSelection.length > 0) return;
      onNavigate();
    });
  }

