  // Full-Text Concordance Search
  function performSearch(query) {
    const resultsContainer = document.getElementById('searchResultsList');
    const summaryEl = document.getElementById('searchSummaryText');
    const trimmed = (query || '').trim();

    if (!trimmed) {
      renderSearchEmptyState(resultsContainer, summaryEl);
      return;
    }

    resultsContainer.innerHTML = '';

    const parsedRef = parseBibleReference(trimmed);
    if (parsedRef) {
      const refBook = bibleData[parsedRef.b];
      const refVerseIdx = parsedRef.v !== null ? parsedRef.v : 0;
      const refText = refBook.chapters[parsedRef.c][refVerseIdx];
      const card = document.createElement('div');
      card.className = 'search-result-card';
      card.style.borderLeft = '4px solid var(--accent)';
      card.innerHTML = `
        <div class="search-result-ref">
          <span>📖 Cita directa: ${escapeHtml(refBook.name)} ${parsedRef.c + 1}${parsedRef.v !== null ? ':' + (parsedRef.v + 1) : ''}</span>
        </div>
        <div class="search-result-text">${formatVerseHtml(refText, parsedRef.b, parsedRef.c, refVerseIdx)}</div>
        ${createCardActionsHtml()}
      `;
      bindCardQuickActions(card, refBook.name, parsedRef.c, refVerseIdx, refText, () => {
        document.getElementById('searchModal').classList.add('hidden');
        navigateTo(parsedRef.b, parsedRef.c, parsedRef.v);
      });
      resultsContainer.appendChild(card);
    }

    const strippedQuotes = trimmed.replace(/^["«“]|["»”]$/g, '').trim();
    const normQuery = normalizeStr(strippedQuotes);
    if (normQuery.length < 2) {
      summaryEl.textContent = parsedRef ? 'Referencia directa encontrada.' : 'Escribe al menos 2 letras para buscar.';
      return;
    }

    const chkExact = document.getElementById('chkExactPhrase');
    const isExactPhrase = chkExact ? chkExact.checked : true;
    const terms = isExactPhrase ? [normQuery] : normQuery.split(/\s+/).filter(Boolean);
    const matches = [];
    const MAX_RESULTS = 250;

    for (let b = 0; b < bibleData.length; b++) {
      const book = bibleData[b];
      if (activeSearchScope === 'AT' && book.testament !== 'AT') continue;
      if (activeSearchScope === 'NT' && book.testament !== 'NT') continue;
      if (activeSearchScope === 'BOOK' && b !== currentBookIdx) continue;

      const chapters = book.chapters;
      for (let c = 0; c < chapters.length; c++) {
        const verses = chapters[c];
        for (let v = 0; v < verses.length; v++) {
          const normVerse = normalizeStr(verses[v]);
          let allMatch = true;
          if (isExactPhrase) {
            allMatch = normVerse.includes(normQuery);
          } else {
            for (let t = 0; t < terms.length; t++) {
              if (!normVerse.includes(terms[t])) {
                allMatch = false;
                break;
              }
            }
          }
          if (allMatch) {
            matches.push({ b, c, v, text: verses[v] });
            if (matches.length >= MAX_RESULTS) break;
          }
        }
        if (matches.length >= MAX_RESULTS) break;
      }
      if (matches.length >= MAX_RESULTS) break;
    }

    if (matches.length === 0 && !parsedRef) {
      summaryEl.textContent = `No se encontraron versículos para "${strippedQuotes}".`;
      resultsContainer.innerHTML = `
        <div class="search-empty-state">
          <h4>Sin resultados</h4>
          <p class="search-empty-desc">
            No se encontraron coincidencias para <strong>"${escapeHtml(strippedQuotes)}"</strong>.${isExactPhrase ? ' Prueba desmarcando <strong>Frase exacta</strong> o revisando el filtro de testamento.' : ''}
          </p>
        </div>
      `;
      return;
    }

    summaryEl.textContent =
      matches.length >= MAX_RESULTS
        ? `Mostrando los primeros ${MAX_RESULTS} resultados para "${strippedQuotes}"`
        : parsedRef && matches.length === 0
          ? `Cita directa encontrada: ${bibleData[parsedRef.b].name} ${parsedRef.c + 1}${parsedRef.v !== null ? ':' + (parsedRef.v + 1) : ''}`
          : `${matches.length} versículo${matches.length === 1 ? '' : 's'} encontrado${matches.length === 1 ? '' : 's'} para "${strippedQuotes}"`;

    matches.forEach((m) => {
      const book = bibleData[m.b];
      const card = document.createElement('div');
      card.className = 'search-result-card';
      card.innerHTML = `
        <div class="search-result-ref">
          <span>${escapeHtml(book.name)} ${m.c + 1}:${m.v + 1}</span>
          <span>${escapeHtml(book.category)}</span>
        </div>
        <div class="search-result-text">${formatVerseHtml(m.text, m.b, m.c, m.v, terms)}</div>
        ${createCardActionsHtml()}
      `;
      bindCardQuickActions(card, book.name, m.c, m.v, m.text, () => {
        document.getElementById('searchModal').classList.add('hidden');
        navigateTo(m.b, m.c, m.v);
      });
      resultsContainer.appendChild(card);
    });
  }

  function highlightQueryTerms(text, normTerms) {
    let safe = escapeHtml(text);
    normTerms.forEach((term) => {
      if (term.length < 2) return;
      const pattern = term
        .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
        .replace(/a/g, '[aá]')
        .replace(/e/g, '[eé]')
        .replace(/i/g, '[ií]')
        .replace(/o/g, '[oó]')
        .replace(/u/g, '[uúü]')
        .replace(/n/g, '[nñ]');
      const regex = new RegExp(`(${pattern})`, 'gi');
      safe = safe.replace(regex, '<mark>$1</mark>');
    });
    return safe;
  }

  // Topics Modal Rendering with Category & Text Filtering
  function renderTopicsModal() {
    const container = document.getElementById('topicsModalBody');
    const filterInput = document.getElementById('topicFilterInput');
    if (!container) return;
    const query = normalizeStr(filterInput ? filterInput.value.trim() : '');
    container.innerHTML = '';

    const filtered = TOPICS_DATA.filter((topic) => {
      if (activeTopicCategory !== 'ALL' && topic.cat !== activeTopicCategory) return false;
      if (!query) return true;
      const hay = normalizeStr(
        `${topic.title} ${topic.desc} ${topic.refs.map((r) => r.label).join(' ')}`
      );
      return hay.includes(query);
    });

    if (!filtered.length) {
      container.innerHTML = '<p class="modal-subtitle">No se encontraron temas que coincidan con tu filtro.</p>';
      return;
    }

    filtered.forEach((topic) => {
      const card = document.createElement('div');
      card.className = 'topic-card';
      const pillsHtml = topic.refs
        .map(
          (r) =>
            `<button class="topic-pill" data-b="${r.b}" data-c="${r.c}" data-v="${r.v}">${escapeHtml(r.label)}</button>`
        )
        .join('');
      card.innerHTML = `
        <div class="topic-title">${escapeHtml(topic.title)}</div>
        <div class="topic-desc">${escapeHtml(topic.desc)}</div>
        <div class="topic-verses">${pillsHtml}</div>
      `;
      card.querySelectorAll('.topic-pill').forEach((btn) => {
        btn.addEventListener('click', () => {
          document.getElementById('topicsModal').classList.add('hidden');
          navigateTo(
            parseInt(btn.dataset.b, 10),
            parseInt(btn.dataset.c, 10),
            parseInt(btn.dataset.v, 10)
          );
        });
      });
      container.appendChild(card);
    });
  }

  // My Study Modal (Favorites, Notes, Highlights, Progress)
  function renderSavedModal() {
    const container = document.getElementById('savedModalBody');
    container.innerHTML = '';

    const parseKey = (k) => k.split('-').map((n) => parseInt(n, 10));

    if (activeSavedTab === 'favorites') {
      const keys = Object.keys(userData.favorites).sort(
        (a, b) => userData.favorites[b] - userData.favorites[a]
      );
      if (!keys.length) {
        container.innerHTML = '<p class="modal-subtitle">Aún no tienes versículos favoritos. Toca cualquier versículo al leer y elige "★ Favorito".</p>';
        return;
      }
      keys.forEach((k) => {
        const [b, c, v] = parseKey(k);
        const book = bibleData[b];
        if (!book) return;
        const vText = book.chapters[c][v];
        const card = document.createElement('div');
        card.className = 'search-result-card';
        card.innerHTML = `
          <div class="search-result-ref">
            <span>★ ${escapeHtml(book.name)} ${c + 1}:${v + 1}</span>
          </div>
          <div class="search-result-text">${formatVerseHtml(vText, b, c, v)}</div>
          ${createCardActionsHtml()}
        `;
        bindCardQuickActions(card, book.name, c, v, vText, () => {
          document.getElementById('savedModal').classList.add('hidden');
          navigateTo(b, c, v);
        });
        container.appendChild(card);
      });
    } else if (activeSavedTab === 'notes') {
      const keys = Object.keys(userData.notes);
      if (!keys.length) {
        container.innerHTML = '<p class="modal-subtitle">Aún no has escrito notas personales. Selecciona un versículo y pulsa "✎ Nota".</p>';
        return;
      }
      keys.forEach((k) => {
        const [b, c, v] = parseKey(k);
        const book = bibleData[b];
        const note = userData.notes[k];
        if (!book || !note) return;
        const vText = book.chapters[c][v];
        const card = document.createElement('div');
        card.className = 'search-result-card';
        card.innerHTML = `
          <div class="search-result-ref">
            <span>✎ ${escapeHtml(book.name)} ${c + 1}:${v + 1}</span>
          </div>
          <div class="search-result-text">${formatVerseHtml(vText, b, c, v)}</div>
          <div class="verse-note-box"><strong>Tu nota:</strong> ${escapeHtml(note.text)}</div>
          ${createCardActionsHtml()}
        `;
        bindCardQuickActions(card, book.name, c, v, vText, () => {
          document.getElementById('savedModal').classList.add('hidden');
          navigateTo(b, c, v);
        }, note.text);
        container.appendChild(card);
      });
    } else if (activeSavedTab === 'highlights') {
      const keys = Object.keys(userData.highlights);
      if (!keys.length) {
        container.innerHTML = '<p class="modal-subtitle">Aún no tienes versículos resaltados. Toca cualquier versículo y elige un color.</p>';
        return;
      }
      keys.forEach((k) => {
        const [b, c, v] = parseKey(k);
        const book = bibleData[b];
        if (!book) return;
        const vText = book.chapters[c][v];
        const card = document.createElement('div');
        card.className = 'search-result-card';
        card.innerHTML = `
          <div class="search-result-ref">
            <span>🖍 ${escapeHtml(book.name)} ${c + 1}:${v + 1}</span>
          </div>
          <div class="search-result-text">${formatVerseHtml(vText, b, c, v)}</div>
          ${createCardActionsHtml()}
        `;
        bindCardQuickActions(card, book.name, c, v, vText, () => {
          document.getElementById('savedModal').classList.add('hidden');
          navigateTo(b, c, v);
        });
        container.appendChild(card);
      });
    } else if (activeSavedTab === 'history') {
      const readTotal = Object.keys(userData.readChapters).length;
      const pct = ((readTotal / TOTAL_BIBLE_CHAPTERS) * 100).toFixed(1);
      const summaryDiv = document.createElement('div');
      summaryDiv.style.marginBottom = '16px';
      summaryDiv.innerHTML = `
        <strong>Progreso general:</strong> ${readTotal} de ${TOTAL_BIBLE_CHAPTERS} capítulos leídos (${pct}%)
      `;
      container.appendChild(summaryDiv);

      userData.history.forEach((h) => {
        const book = bibleData[h.b];
        if (!book) return;
        const card = document.createElement('div');
        card.className = 'search-result-card';
        card.innerHTML = `
          <div class="search-result-ref">
            <span>🕒 ${escapeHtml(book.name)} ${h.c + 1}</span>
            <span>Volver a leer →</span>
          </div>
        `;
        card.addEventListener('click', () => {
          document.getElementById('savedModal').classList.add('hidden');
          navigateTo(h.b, h.c);
        });
        container.appendChild(card);
      });
    }
  }

